param location string = resourceGroup().location
param openAIResourceId string

resource webApp 'Microsoft.Web/sites@2023-12-01' = {
  name: 'my-web-app'
  location: location
  identity: {
    type: 'SystemAssigned'
  }
  properties: {
    serverFarmId: appServicePlan.id
  }
}

// Grant the web app's managed identity access to Azure OpenAI
resource openAIRoleAssignment 'Microsoft.Authorization/roleAssignments@2022-04-01' = {
  name: '${webApp.name}-openai-access'
  scope: openAIResourceId
  properties: {
    roleDefinitionId: '${subscription().subscriptionId}/providers/Microsoft.Authorization/roleDefinitions/a97a65e1-6c7d-4d2e-9d2c-6c7e3d2a1b0f'
    principalId: webApp.identity.principalId
    principalType: 'ServicePrincipal'
  }
}

output webAppPrincipalId string = webApp.identity.principalId

using Azure;
using Azure.AI.OpenAI;
using Azure.Identity;

// DefaultAzureCredential automatically uses managed identity in Azure
// and falls back to local development credentials (VS, Azure CLI)
var credential = new DefaultAzureCredential();

var openAIClient = new OpenAIClient(
    new Uri("https://my-openai.openai.azure.com/"),
    credential);

var chatCompletionsOptions = new ChatCompletionsOptions()
{
    DeploymentName = "gpt4o",
    Messages =
    {
        new ChatMessage(ChatRole.User, "What is Azure App Service?")
    }
};

ChatCompletions response = await openAIClient.GetChatCompletionsAsync(chatCompletionsOptions);
Console.WriteLine(response.Choices[0].Message.Content);
